using System.Collections.Generic;
using UnityEngine;

namespace PulseArena.Game
{
    /// Procedural tile geometry, built in code (D13). Nothing is imported or generated by a tool. A tile is one rounded slab
    /// with a flat emblem standing on its top face. Submesh 0 is the slab (its symbol colour), submesh 1 is the emblem
    /// (its own shared material). Each symbol has its own emblem shape, so colour is never the only cue. Sizes are in local
    /// units; MatchController scales a tile by TileScale.
    public static class TileMeshes
    {
        public const int ShapeCount = 7;

        private const float HalfWidth = 0.5f;          // the slab footprint is 1 x 1
        private const float Corner = 0.16f;            // corner radius of the footprint
        private const float HalfHeight = 0.3f;         // the slab is 0.6 units thick
        private const float Bevel = 0.07f;             // rounding on the top and bottom edges
        private const float EmblemHeight = 0.06f;      // the emblem stands this far above the top face
        private const int CornerSegments = 4;
        private const float Tilt = 0.7f;               // how much the bevel normals lean away from the face

        /// The seven emblem outlines. Each is star-shaped about the centre, so a fan from the centre triangulates it.
        private static readonly Vector2[][] Emblems = BuildEmblems();

        /// One mesh per emblem shape, built once per match. Index with symbol % ShapeCount.
        public static Mesh[] CreateTiles()
        {
            var meshes = new Mesh[ShapeCount];
            for (int shape = 0; shape < ShapeCount; shape++)
            {
                var verts = new List<Vector3>();
                var normals = new List<Vector3>();
                var body = new List<int>();
                var emblem = new List<int>();
                AddSlab(verts, normals, body);
                AddEmblem(verts, normals, emblem, Emblems[shape]);
                meshes[shape] = Finish(verts, normals, body, emblem);
            }

            return meshes;
        }

        /// A plain slab, the same footprint and thickness as a tile body, for the board plate and the tray well.
        public static Mesh CreateSlab()
        {
            var verts = new List<Vector3>();
            var normals = new List<Vector3>();
            var body = new List<int>();
            AddSlab(verts, normals, body);
            return Finish(verts, normals, body);
        }

        private static Mesh Finish(List<Vector3> verts, List<Vector3> normals, params List<int>[] submeshes)
        {
            var mesh = new Mesh();
            mesh.vertices = verts.ToArray();
            mesh.normals = normals.ToArray();
            mesh.subMeshCount = submeshes.Length;
            for (int i = 0; i < submeshes.Length; i++)
            {
                mesh.SetTriangles(submeshes[i].ToArray(), i);
            }

            mesh.RecalculateBounds();
            return mesh;
        }

        // The slab: four rings from bottom to top. The top and bottom rims are inset by the bevel, so the edges round off.
        // The top and bottom faces get their own vertices, so their normals stay flat and the edges read as hard.
        private static void AddSlab(List<Vector3> verts, List<Vector3> normals, List<int> tris)
        {
            var rimPos = new List<Vector2>();
            var rimDir = new List<Vector2>();
            var fullPos = new List<Vector2>();
            var fullDir = new List<Vector2>();
            Outline(HalfWidth - Bevel, Corner - Bevel, rimPos, rimDir);
            Outline(HalfWidth, Corner, fullPos, fullDir);
            int n = rimPos.Count;

            int ring0 = verts.Count;
            for (int i = 0; i < n; i++)
            {
                verts.Add(new Vector3(rimPos[i].x, -HalfHeight, rimPos[i].y));
                normals.Add(Normalized(rimDir[i].x * Tilt, -Tilt, rimDir[i].y * Tilt));
            }

            int ring1 = verts.Count;
            for (int i = 0; i < n; i++)
            {
                verts.Add(new Vector3(fullPos[i].x, -HalfHeight + Bevel, fullPos[i].y));
                normals.Add(new Vector3(fullDir[i].x, 0f, fullDir[i].y));
            }

            int ring2 = verts.Count;
            for (int i = 0; i < n; i++)
            {
                verts.Add(new Vector3(fullPos[i].x, HalfHeight - Bevel, fullPos[i].y));
                normals.Add(new Vector3(fullDir[i].x, 0f, fullDir[i].y));
            }

            int ring3 = verts.Count;
            for (int i = 0; i < n; i++)
            {
                verts.Add(new Vector3(rimPos[i].x, HalfHeight, rimPos[i].y));
                normals.Add(Normalized(rimDir[i].x * Tilt, Tilt, rimDir[i].y * Tilt));
            }

            int[] rings = { ring0, ring1, ring2, ring3 };
            for (int r = 0; r < rings.Length - 1; r++)
            {
                for (int i = 0; i < n; i++)
                {
                    int next = (i + 1) % n;
                    int a = rings[r] + i;
                    int b = rings[r] + next;
                    int c = rings[r + 1] + next;
                    int d = rings[r + 1] + i;
                    AddTri(verts, tris, a, b, c, normals[a]);
                    AddTri(verts, tris, a, c, d, normals[a]);
                }
            }

            int topCentre = verts.Count;
            verts.Add(new Vector3(0f, HalfHeight, 0f));
            normals.Add(Vector3.up);
            int topRing = verts.Count;
            for (int i = 0; i < n; i++)
            {
                verts.Add(new Vector3(rimPos[i].x, HalfHeight, rimPos[i].y));
                normals.Add(Vector3.up);
            }

            for (int i = 0; i < n; i++)
            {
                AddTri(verts, tris, topCentre, topRing + i, topRing + (i + 1) % n, Vector3.up);
            }

            int bottomCentre = verts.Count;
            verts.Add(new Vector3(0f, -HalfHeight, 0f));
            normals.Add(Vector3.down);
            int bottomRing = verts.Count;
            for (int i = 0; i < n; i++)
            {
                verts.Add(new Vector3(rimPos[i].x, -HalfHeight, rimPos[i].y));
                normals.Add(Vector3.down);
            }

            for (int i = 0; i < n; i++)
            {
                AddTri(verts, tris, bottomCentre, bottomRing + i, bottomRing + (i + 1) % n, Vector3.down);
            }
        }

        // The emblem: a flat extruded outline standing on the top face. Its sides have one normal per edge, so they stay crisp.
        private static void AddEmblem(List<Vector3> verts, List<Vector3> normals, List<int> tris, Vector2[] outline)
        {
            int n = outline.Length;
            float low = HalfHeight;
            float high = HalfHeight + EmblemHeight;
            for (int i = 0; i < n; i++)
            {
                Vector2 p = outline[i];
                Vector2 q = outline[(i + 1) % n];
                float ex = q.y - p.y;
                float ez = p.x - q.x;   // the edge's perpendicular; flipped below if it points inward
                float mx = (p.x + q.x) * 0.5f;
                float mz = (p.y + q.y) * 0.5f;
                if (ex * mx + ez * mz < 0f)
                {
                    ex = -ex;
                    ez = -ez;
                }

                Vector3 normal = Normalized(ex, 0f, ez);
                int v = verts.Count;
                verts.Add(new Vector3(p.x, low, p.y));
                verts.Add(new Vector3(q.x, low, q.y));
                verts.Add(new Vector3(q.x, high, q.y));
                verts.Add(new Vector3(p.x, high, p.y));
                for (int k = 0; k < 4; k++)
                {
                    normals.Add(normal);
                }

                AddTri(verts, tris, v, v + 1, v + 2, normal);
                AddTri(verts, tris, v, v + 2, v + 3, normal);
            }

            int centre = verts.Count;
            verts.Add(new Vector3(0f, high, 0f));
            normals.Add(Vector3.up);
            int ring = verts.Count;
            for (int i = 0; i < n; i++)
            {
                verts.Add(new Vector3(outline[i].x, high, outline[i].y));
                normals.Add(Vector3.up);
            }

            for (int i = 0; i < n; i++)
            {
                AddTri(verts, tris, centre, ring + i, ring + (i + 1) % n, Vector3.up);
            }
        }

        // Adds a triangle with its winding set so its face points the way the desired normal says.
        private static void AddTri(List<Vector3> verts, List<int> tris, int a, int b, int c, Vector3 desired)
        {
            Vector3 facing = Vector3.Cross(verts[b] - verts[a], verts[c] - verts[a]);
            if (Vector3.Dot(facing, desired) < 0f)
            {
                (b, c) = (c, b);
            }

            tris.Add(a);
            tris.Add(b);
            tris.Add(c);
        }

        // Points around a rounded rectangle, with the outward direction at each point. Four corners, CornerSegments steps each.
        private static void Outline(float half, float radius, List<Vector2> pos, List<Vector2> dir)
        {
            pos.Clear();
            dir.Clear();
            float core = half - radius;
            for (int corner = 0; corner < 4; corner++)
            {
                float cx = (corner == 0 || corner == 3) ? core : -core;
                float cz = (corner == 0 || corner == 1) ? core : -core;
                for (int step = 0; step <= CornerSegments; step++)
                {
                    float angle = (corner * 90f + step * 90f / CornerSegments) * Mathf.Deg2Rad;
                    float dx = Mathf.Cos(angle);
                    float dz = Mathf.Sin(angle);
                    pos.Add(new Vector2(cx + radius * dx, cz + radius * dz));
                    dir.Add(new Vector2(dx, dz));
                }
            }
        }

        private static Vector3 Normalized(float x, float y, float z)
        {
            float length = Mathf.Sqrt(x * x + y * y + z * z);
            return length > 0f ? new Vector3(x / length, y / length, z / length) : Vector3.up;
        }

        private static Vector2[][] BuildEmblems()
        {
            var shapes = new Vector2[ShapeCount][];

            // 0: circle
            shapes[0] = Regular(24, 0.33f, 0f);

            // 1: square, sharp corners
            shapes[1] = new[]
            {
                new Vector2(0.25f, 0.25f), new Vector2(-0.25f, 0.25f), new Vector2(-0.25f, -0.25f), new Vector2(0.25f, -0.25f)
            };

            // 2: triangle, point up
            shapes[2] = new[]
            {
                new Vector2(0f, 0.35f), new Vector2(-0.3f, -0.175f), new Vector2(0.3f, -0.175f)
            };

            // 3: diamond, tall and narrow, so it does not read as the square turned
            shapes[3] = new[]
            {
                new Vector2(0f, 0.39f), new Vector2(-0.24f, 0f), new Vector2(0f, -0.39f), new Vector2(0.24f, 0f)
            };

            // 4: five-point star
            var star = new Vector2[10];
            for (int k = 0; k < 10; k++)
            {
                float radius = k % 2 == 0 ? 0.36f : 0.155f;
                float angle = (90f + k * 36f) * Mathf.Deg2Rad;
                star[k] = new Vector2(radius * Mathf.Cos(angle), radius * Mathf.Sin(angle));
            }

            shapes[4] = star;

            // 5: plus sign
            const float w = 0.11f;
            const float l = 0.33f;
            shapes[5] = new[]
            {
                new Vector2(w, l), new Vector2(w, w), new Vector2(l, w), new Vector2(l, -w), new Vector2(w, -w), new Vector2(w, -l),
                new Vector2(-w, -l), new Vector2(-w, -w), new Vector2(-l, -w), new Vector2(-l, w), new Vector2(-w, w), new Vector2(-w, l)
            };

            // 6: hexagon, flat sides on top
            shapes[6] = Regular(6, 0.33f, 0f);
            return shapes;
        }

        private static Vector2[] Regular(int sides, float radius, float offsetDegrees)
        {
            var points = new Vector2[sides];
            for (int i = 0; i < sides; i++)
            {
                float angle = (offsetDegrees + i * 360f / sides) * Mathf.Deg2Rad;
                points[i] = new Vector2(radius * Mathf.Cos(angle), radius * Mathf.Sin(angle));
            }

            return points;
        }
    }
}
